#!/usr/bin/env python3
"""Read-only exploratory reader for FM24 database .dat containers.

Verified decoders cover table_21 stadium rows, table_25 competition identifiers,
table_41 currency rows, and table_56 structural triples. Table_10 is reported as
an opaque payload until its variable record serializer is recovered.
"""
from __future__ import annotations

import argparse
import hashlib
import io
import json
import re
import struct
import sys
from pathlib import Path, PurePosixPath
from typing import Any, Iterator

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_DB_DIR = Path(
    "Z:/SteamLibrary/steamapps/common/Football Manager 2024/data/database/db/2430/2430_fm"
)
ZSTD_MAGIC = bytes.fromhex("28b52ffd")
FMF_MAGIC = bytes.fromhex("0201666d662e080000")
DAT_MAGIC = b"\x03\x01tad."
MAX_DIRECTORY_SIZE = 16 * 1024 * 1024
MAX_ENTRY_SIZE = 256 * 1024 * 1024
MAX_STRING_SIZE = 1024 * 1024

# These are evidence-weighted hypotheses, not a recovered table-type enum.
TABLE_HINTS = {
    8: {"entity": "language", "confidence": "candidate", "basis": "readable language names in table_8"},
    10: {"entity": "nation", "confidence": "strong candidate", "basis": "DBC type 10 properties reverse-map to nation.xml; table_10 has 251 rows and contains duni 472446402670"},
    21: {"entity": "stadium", "confidence": "high", "basis": "all 48,413 rows have rdui=row_index and repeated-u32 duni; DBC type 21 Ssds maps to stadium.xml; server rows contain an 8-slot side block"},
    25: {"entity": "competition", "confidence": "high", "basis": "client rows have 127-byte stride and duni at row+118; DBC type 25 properties reverse-map to comp.xml"},
    41: {"entity": "currency", "confidence": "high candidate", "basis": "173 currency names, rate series, and currency schema fields in table_41"},
}

# Byte layouts established by exact size/count arithmetic and identity checks.
# Offsets are relative to each row; row data begins after a 14-byte payload header.
TABLE_ROW_LAYOUTS = {
    "client_db.dat": {
        21: {"header_size": 14, "stride": 38, "rdui_offset": 25, "duni_offset": 29},
        25: {"header_size": 14, "stride": 127, "duni_offset": 118},
    },
    "server_db.dat": {
        21: {"header_size": 14, "stride": 181, "rdui_offset": 168, "duni_offset": 172},
    },
}


def _zstd_module():
    """Import the workspace-pinned dependency under python -I."""
    vendor = ROOT / "tools" / "python"
    if str(vendor) not in sys.path:
        sys.path.insert(0, str(vendor))
    try:
        import zstandard as zstd
    except ImportError as exc:
        raise RuntimeError(
            f"zstandard not found; expected the workspace dependency under {vendor}"
        ) from exc
    return zstd


def _stream_decompress(frame: bytes, limit: int) -> bytes:
    if not frame.startswith(ZSTD_MAGIC):
        raise ValueError(f"missing Zstandard frame: {frame[:8].hex()}")
    zstd = _zstd_module()
    with zstd.ZstdDecompressor().stream_reader(
        io.BytesIO(frame), read_across_frames=False
    ) as reader:
        result = reader.read(limit + 1)
    if len(result) > limit:
        raise ValueError(f"Zstandard output exceeds safety limit ({limit} bytes)")
    return result


class _DirectoryReader:
    def __init__(self, data: bytes):
        self.data = data
        self.pos = 0
        self.entries: list[dict[str, Any]] = []

    def take(self, count: int) -> bytes:
        if count < 0 or self.pos + count > len(self.data):
            raise ValueError(f"truncated FMF directory at 0x{self.pos:x}")
        value = self.data[self.pos : self.pos + count]
        self.pos += count
        return value

    def u32(self) -> int:
        return struct.unpack("<I", self.take(4))[0]

    def string(self) -> str:
        length = self.u32()
        if length > MAX_STRING_SIZE:
            raise ValueError(f"oversized FMF directory string: {length}")
        return self.take(length).decode("utf-8")

    def directory(self, parent: PurePosixPath = PurePosixPath(), depth: int = 0) -> None:
        if depth > 40:
            raise ValueError("FMF directory nesting exceeds 40")
        folder = self.string()
